                    parents[(nr, nc)] = (r, c)
                    if (nr, nc) in other:
                        return (nr, nc)
                    queue.append((nr, nc))
        return None

    meet = None
    while q_fwd and q_bwd:
        meet = expand(q_fwd, parent_fwd, parent_bwd)
        if meet:
            break
        meet = expand(q_bwd, parent_bwd, parent_fwd)
