def solve(intervals):
    if not intervals:
        return []

    # Sort intervals by start time
    intervals.sort()

    # Build an interval tree
    class IntervalTreeNode:
        def __init__(self, start, end):
            self.start = start
            self.end = end
            self.left = None
            self.right = None

    def insert(node, start, end):
        if node is None:
            return IntervalTreeNode(start, end)
        if end < node.start:
            node.left = insert(node.left, start, end)
        elif start > node.end:
            node.right = insert(node.right, start, end)
        else:
            # Overlapping, merge intervals
            node.start = min(node.start, start)
            node.end = max(node.end, end)
        return node

    root = None
    for interval in intervals:
        root = insert(root, interval[0], interval[1])

    # Traverse the tree to collect merged intervals
    merged = []
    def traverse(node):
        if node is None:
            return
        traverse(node.left)
        merged.append([node.start, node.end])
        traverse(node.right)

    traverse(root)
    return merged

def solve(grid, start, goal):
    # Helper function to get the orthogonal neighbours of a cell.
    def get_neighbours(row, col):
        neighbours = []
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            r, c = row + dr, col + dc
            if 0 <= r < len(grid) and 0 <= c < len(grid[0]) and grid[r][c] != '#':
                neighbours.append((r, c))
        return neighbours

    # Helper function to map a grid cell to a tuple with its cost, row, and column.
    def grid_to_cost(row, col):
        if grid[row][col] == '#':
            return float('inf'), 0, 0
        return 0, row, col

    # Check if the start or goal is a wall.
    if grid[start[0]][start[1]] == '#' or grid[goal[0]][goal[1]] == '#':
        return []

    # Get the possible moves.
    moves = get_neighbours(start[0], start[1])

    # An implementation of A* search using two priority queues.
    open_priority_queue = [(0, start)]  # The open list.
    came_from = {}  # The dictionary mapping each node to the node that was the parent of this node during the tree reconstruction.
    cost_so_far = {start: 0}  # The cost from start to each node.
    while open_priority_queue:
        _, current = min(open_priority_queue)
        if current == goal:
            break
        open_priority_queue.remove(min(open_priority_queue))
        for neighbour in get_neighbours(*current):
            new_cost = cost_so_far[current] + 1
            if neighbour not in cost_so_far or new_cost < cost_so_far[neighbour]:
                cost_so_far[neighbour] = new_cost
                priority = new_cost + manhattan_distance(*current, *goal)
                open_priority_queue.append((priority, neighbour))
                came_from[neighbour] = current
    else:
        return []  # No path.

    # Reconstruct the path.
    current = goal
    path = [current]
    while current != start:
        current = came_from[current]
        path.insert(0, current)
    return path

