    def is_valid(pos):
        r, c = pos
        return 0 <= r < len(grid) and 0 <= c < len(grid[0]) and grid[r][c] == '.'

    def bfs(from_pos, visited, other_visited):
        queue = deque([(from_pos, [from_pos])])
        visited.add(from_pos)
        directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
        while queue:
            current, path = queue.popleft()
            for dr, dc in directions:
                nr, nc = current[0] + dr, current[1] + dc
                next_pos = (nr, nc)
                if is_valid(next_pos):
                    if next_pos in other_visited:
                        return path + [next_pos]
                    if next_pos not in visited:
                        visited.add(next_pos)
                        queue.append((next_pos, path + [next_pos]))
        return []

    start_visited = set()
    goal_visited = set()
    start_queue = deque([start])
    goal_queue = deque([goal])
    start_visited.add(start)
    goal_visited.add(goal)

    while start_queue and goal_queue:
        result = bfs(start_queue.popleft(), start_visited, goal_visited)
        if result:
            return result
        result = bfs(goal_queue.popleft(), goal_visited, start_visited)
        if result:
            return result
    return []

