def solve(n, edges, s, t):
    def construct_graph(n, edges):
        graph = [[] for _ in range(n)]
        for u, v, w in edges:
            graph[u].append((v, w))
        return graph

    graph = construct_graph(n, edges)
    dist = [sys.maxsize // 2] * n
    dist[s] = 0

    pq = [s]

    while pq:
        u = heapq.heappop(pq)
        for v, w in graph[u]:
            new_dist = dist[u] + w
            if new_dist < dist[v]:
                dist[v] = new_dist
                heapq.heappush(pq, v)

    return dist[t] if dist[t] != sys.maxsize // 2 else -1

